INSERT INTO `gmsurveyquestions_dbc` VALUES (28,'Did the GM provide an appropriate answer or solution to your question/problem?','','Le MJ a-t-il apporté une réponse ou une solution adaptée à votre question/problème ?','','','','','','','','','','','','','',16712190),(29,'How easy was it to understand and/or follow the information provided?','','L’information fournie était-elle facile à comprendre et/ou à appliquer ?','','','','','','','','','','','','','',16712190),(30,'Was the GM knowledgeable, respectful, and empathetic during your interactions?','','Au cours de vos échanges, le MJ était-il informé, poli et compréhensif ?','','','','','','','','','','','','','',16712190),(31,'How would you rate the response time to address your petition?','','Quelle note donneriez-vous au temps de réponse à votre requête ?','','','','','','','','','','','','','',16712190),(32,'How would you rate the overall experience with the GM that assisted you with your petition?','','Quelle note donneriez-vous quant à votre expérience avec le MJ qui vous a aidé dans votre requête ?','','','','','','','','','','','','','',16712190),(33,'Based on your support experience, how likely is it that you would recommend WoW to others?','','En vous basant sur votre expérience de l\'assistance en jeu, recommanderiez-vous WoW à d’autres personnes ?','','','','','','','','','','','','','',16712190),(35,'Based on this customer service experience, how likely are you to recommend Blizzard products and services to a friend?','','Suite à cette expérience avec le service clientèle de Blizzard, seriez-vous prêt à recommander les produits et services de Blizzard à vos amis ?','','','','','','','','','','','','','',16712190),(36,'Was your problem solved?','','Votre problème est-il résolu ?','','','','','','','','','','','','','',16712190),(37,'My overall experience with Blizzard Customer Service was:','','De manière générale, mon expérience avec le service clientèle de Blizzard était :','','','','','','','','','','','','','',16712190),(38,'My wait time for Blizzard Customer Service was:','','Le délai de réponse du service d’assistance de Blizzard était :','','','','','','','','','','','','','',16712190),(39,'This Blizzard Representative’s professionalism was:','','Le professionnalisme de ce représentant de Blizzard était :','','','','','','','','','','','','','',16712190),(40,'This Blizzard Representative’s communication skills were:','','Les explications de ce représentant de Blizzard étaient :','','','','','','','','','','','','','',16712190),(41,'This Blizzard Representative’s overall service was:','','De manière générale, l\'aide de ce représentant de Blizzard était :','','','','','','','','','','','','','',16712190);
